        "async function firmarRecepcionLaboratorioUI(id, boton) {\n  if (firmaLabRecepcionFinalVacia) {\n    document.getElementById('labDetalleError').textContent = 'Falta la firma de quien deja el trabajo';\n    return;\n  }\n  const firma_recepcion = document.getElementById('lab_firma_recepcion_canvas').toDataURL('image/png');\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      await api(`/api/laboratorio/${id}/firmar-recepcion`, { method: 'POST', body: JSON.stringify({ firma_recepcion }) });\n      mostrarExito('Firma registrada');\n      await abrirDetalleLaboratorio(id);\n    } catch (e) {\n      document.getElementById('labDetalleError').textContent = e.message;\n    }\n  });\n}\n\nasync function eliminarTrabajoLaboratorioUI(id) {",
        'async function firmarRecepcionLaboratorioUI(id, boton) {\n  if (firmaLabRecepcionFinalVacia) {\n    document.getElementById(\'labDetalleError\').textContent = \'Falta la firma de quien deja el trabajo\';\n    return;\n  }\n  const firma_recepcion = document.getElementById(\'lab_firma_recepcion_canvas\').toDataURL(\'image/png\');\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      await api(`/api/laboratorio/${id}/firmar-recepcion`, { method: \'POST\', body: JSON.stringify({ firma_recepcion }) });\n      mostrarExito(\'Firma registrada\');\n      await abrirDetalleLaboratorio(id);\n    } catch (e) {\n      document.getElementById(\'labDetalleError\').textContent = e.message;\n    }\n  });\n}\n\n// ---- Pago por transferencia reportado por un estudiante (Fase 2, sin\n// Mercado Pago todavia) -- la IA solo sugirio los datos al leer la foto, el\n// laboratorio siempre confirma a mano contra el banco antes de que cuente. ----\nfunction abrirConfirmarPagoReportadoLaboratorio(reporteId, trabajoId, montoSugerido) {\n  document.getElementById(\'modalContent\').innerHTML = `\n    <button class="close-btn" onclick="cerrarModal()">cerrar</button>\n    <h2>Confirmar pago reportado</h2>\n    <p style="font-size:12px; color:var(--muted);">Verifica en el banco que el pago sí llegó y captura cómo quedó cubierto — puedes dividirlo entre varios métodos.</p>\n    <div id="lpr_metodos">\n      ${(META.tipos_metodo_pago_laboratorio || [\'efectivo\',\'tarjeta_debito\',\'tarjeta_credito\',\'transferencia\',\'otro\']).map(m => `\n        <div class="row-2" style="align-items:center; margin-bottom:6px;">\n          <label style="font-size:13px; display:flex; align-items:center; gap:6px;">\n            <input type="checkbox" class="lpr_metodo_check" value="${m}" onchange="_lprToggleMetodo(\'${m}\', this.checked)" style="width:auto;" ${m === \'transferencia\' ? \'checked\' : \'\'} />\n            ${NOMBRES_METODO_PAGO_LAB[m] || m}\n          </label>\n          <input type="number" min="0" step="0.01" class="lpr_metodo_monto" id="lpr_monto_${m}" placeholder="Monto" ${m === \'transferencia\' ? \'\' : \'disabled\'} oninput="_lprActualizarTotal()" />\n        </div>\n      `).join(\'\')}\n    </div>\n    <p style="font-size:13px; margin:8px 0;">Total: <b id="lpr_total">$0.00</b></p>\n    <button class="primary" style="width:100%; margin-top:10px;" onclick="confirmarPagoReportadoLaboratorioUI(${reporteId}, ${trabajoId}, this)">Confirmar pago</button>\n    <div id="lprError" class="error-msg"></div>\n  `;\n  abrirModal();\n  if (montoSugerido) {\n    document.getElementById(\'lpr_monto_transferencia\').value = montoSugerido;\n  }\n  _lprActualizarTotal();\n}\n\nfunction _lprToggleMetodo(metodo, activo) {\n  document.getElementById(`lpr_monto_${metodo}`).disabled = !activo;\n  if (!activo) document.getElementById(`lpr_monto_${metodo}`).value = \'\';\n  _lprActualizarTotal();\n}\n\nfunction _lprActualizarTotal() {\n  let total = 0;\n  document.querySelectorAll(\'.lpr_metodo_monto\').forEach(inp => { if (!inp.disabled) total += parseFloat(inp.value) || 0; });\n  document.getElementById(\'lpr_total\').textContent = _fmtC(total);\n}\n\nasync function confirmarPagoReportadoLaboratorioUI(reporteId, trabajoId, boton) {\n  const errEl = document.getElementById(\'lprError\');\n  const metodos = [];\n  document.querySelectorAll(\'.lpr_metodo_check\').forEach(chk => {\n    if (chk.checked) {\n      const monto = parseFloat(document.getElementById(`lpr_monto_${chk.value}`).value);\n      if (monto > 0) metodos.push({ metodo: chk.value, monto });\n    }\n  });\n  if (!metodos.length) {\n    errEl.textContent = \'Marca al menos un método de pago con su monto\';\n    return;\n  }\n  await conBloqueoDeBoton(boton, async () => {\n    try {\n      await api(`/api/laboratorio/pagos-reportados/${reporteId}/confirmar`, { method: \'POST\', body: JSON.stringify({ metodos }) });\n      cerrarModal();\n      mostrarExito(\'Pago confirmado — ya puedes marcar los dientes en el odontograma\');\n      await abrirDetalleLaboratorio(trabajoId);\n      await renderListaLaboratorio();\n    } catch (e) {\n      errEl.textContent = e.message;\n    }\n  });\n}\n\nasync function rechazarPagoReportadoLaboratorioUI(reporteId, trabajoId) {\n  const motivo = prompt(\'¿Por qué se rechaza este pago reportado? (el estudiante lo verá)\');\n  if (motivo === null) return;\n  if (!motivo.trim()) { alert(\'Escribe un motivo\'); return; }\n  try {\n    await api(`/api/laboratorio/pagos-reportados/${reporteId}/rechazar`, { method: \'POST\', body: JSON.stringify({ motivo: motivo.trim() }) });\n    mostrarExito(\'Pago rechazado\');\n    await abrirDetalleLaboratorio(trabajoId);\n  } catch (e) {\n    alert(e.message);\n  }\n}\n\nasync function eliminarTrabajoLaboratorioUI(id) {',
